//! Speech articulation times and the syllable-count extension.
//!
//! `get-art-time` (`core-modules/speech.lisp:223`) uses `:syllable-rate` and
//! `:char-per-syllable`.  The optional syllable-count extension
//! (`extras/syllable-count/syllable-count.lisp`) adds a user table and the
//! CMU pronunciation dictionary, plus `:use-syllable-table` and
//! `:split-vocal-strings`.

use std::collections::HashMap;
use std::sync::{Mutex, OnceLock};

/// Front-coded table generated by `tools/build-syllable-table.py` from
/// `extras/syllable-count/counts.lisp`.
const SYLLABLE_DATA: &[u8] = include_bytes!("../data/syllable_table.bin");
const MAGIC: &[u8; 8] = b"ACTRSYL1";

static BUILTIN: OnceLock<HashMap<String, u8>> = OnceLock::new();
static USER: OnceLock<Mutex<HashMap<String, u8>>> = OnceLock::new();

fn builtin() -> &'static HashMap<String, u8> {
    BUILTIN.get_or_init(decode_table)
}

fn user() -> &'static Mutex<HashMap<String, u8>> {
    USER.get_or_init(|| Mutex::new(HashMap::new()))
}

fn lock_user() -> std::sync::MutexGuard<'static, HashMap<String, u8>> {
    user()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
}

fn decode_table() -> HashMap<String, u8> {
    let mut map = HashMap::new();
    if SYLLABLE_DATA.len() < 12 || &SYLLABLE_DATA[..8] != MAGIC {
        return map;
    }
    let count = u32::from_le_bytes(SYLLABLE_DATA[8..12].try_into().unwrap()) as usize;
    let mut pos = 12;
    let mut previous: Vec<u8> = Vec::new();
    for _ in 0..count {
        if pos + 2 > SYLLABLE_DATA.len() {
            break;
        }
        let prefix = SYLLABLE_DATA[pos] as usize;
        let suffix = SYLLABLE_DATA[pos + 1] as usize;
        pos += 2;
        if prefix > previous.len() || pos + suffix + 1 > SYLLABLE_DATA.len() {
            break;
        }
        let mut word = previous[..prefix].to_vec();
        word.extend_from_slice(&SYLLABLE_DATA[pos..pos + suffix]);
        pos += suffix;
        let syllables = SYLLABLE_DATA[pos];
        pos += 1;
        if let Ok(word) = String::from_utf8(word.clone()) {
            map.insert(word, syllables);
        }
        previous = word;
    }
    map
}

pub(super) fn syllable_count(word: &str) -> Option<u8> {
    let key = word.to_uppercase();
    if let Some(count) = lock_user().get(&key) {
        return Some(*count);
    }
    builtin().get(&key).copied()
}

pub(super) fn register_syllable_count(word: &str, syllables: u8) {
    lock_user().insert(word.to_uppercase(), syllables);
}

pub(super) fn remove_syllable_count(word: &str) -> bool {
    lock_user().remove(&word.to_uppercase()).is_some()
}

impl super::Engine {
    /// `get-art-time` (`speech.lisp:223`) plus the syllable-count extension:
    /// an explicit articulation-time entry always wins, otherwise words use
    /// the CMU table when enabled and fall back to `:char-per-syllable`.
    pub fn articulation_time_ms(&self, text: &str) -> i64 {
        if let Some(ms) = self.articulation_times.get(text) {
            return *ms;
        }
        self.default_articulation_time(text)
    }

    fn default_articulation_time(&self, text: &str) -> i64 {
        let rate = self.cfg.syllable_rate_ms;
        let chars = text.chars().count() as f32;
        let base = (rate as f32 * chars / self.cfg.char_per_syllable)
            .round()
            .max(rate as f32) as i64;
        if !self.cfg.split_vocal_strings && !self.cfg.use_syllable_table {
            return base;
        }
        let words: Vec<&str> = if self.cfg.split_vocal_strings {
            text.split_whitespace().collect()
        } else {
            vec![text]
        };
        if words.is_empty() {
            return base;
        }
        if words.len() == 1 {
            if self.cfg.use_syllable_table {
                if let Some(syllables) = syllable_count(words[0]) {
                    return rate * syllables as i64;
                }
            }
            return base;
        }
        let mut total = rate * (words.len() - 1) as i64;
        for word in words {
            total += self.articulation_time_ms(word);
        }
        total
    }

    pub fn register_articulation_time(&mut self, text: String, time_ms: i64) {
        self.articulation_times.insert(text, time_ms.max(0));
    }

    pub fn get_articulation_time(&self, text: &str, time_in_ms: bool) -> f64 {
        let ms = self.articulation_time_ms(text);
        if time_in_ms {
            ms as f64
        } else {
            ms as f64 / 1000.0
        }
    }

    pub fn get_syllable_count(&self, word: &str) -> Option<u8> {
        syllable_count(word)
    }

    pub fn register_syllable_count(&self, word: &str, syllables: u8) {
        register_syllable_count(word, syllables);
    }

    pub fn remove_syllable_count(&self, word: &str) -> bool {
        remove_syllable_count(word)
    }
}
